const metadata = $input.item.json.metadata || {};
const imageFile = $input.item.binary?.image;
const imageUrl = $input.item.json.image_url;
const network = $input.item.json.network || 'ethereum';
const collection = $input.item.json.collection;

if (!metadata.name) {
  throw new Error('NFT name is required in metadata');
}

if (!imageFile && !imageUrl) {
  throw new Error('Image file or URL is required');
}

return {
  json: {
    mint_id: `nft_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    timestamp: new Date().toISOString(),
    network: network,
    collection: collection || 'default',
    metadata: {
      name: metadata.name,
      description: metadata.description || '',
      attributes: metadata.attributes || [],
      external_url: metadata.external_url || '',
      animation_url: metadata.animation_url || ''
    },
    image_source: imageFile ? 'upload' : 'url',
    image_url: imageUrl
  },
  binary: imageFile ? { image: imageFile } : undefined
};

const ipfsHash = $input.item.json.IpfsHash;
const metadata = $('Validate NFT Data').item.json.metadata;

// Create NFT metadata following ERC-721 standard
const nftMetadata = {
  name: metadata.name,
  description: metadata.description,
  image: `ipfs://${ipfsHash}`,
  external_url: metadata.external_url,
  animation_url: metadata.animation_url,
  attributes: metadata.attributes,
  properties: {
    created_by: 'n8n_automation',
    timestamp: new Date().toISOString()
  }
};

return {
  json: {
    ...nftMetadata,
    image_ipfs_hash: ipfsHash,
    image_ipfs_url: `https://gateway.pinata.cloud/ipfs/${ipfsHash}`
  }
};

const mintResult = JSON.parse($input.item.json);
const baseData = $('Validate NFT Data').item.json;
const metadataHash = $('Pinata - Upload Metadata to IPFS').item.json.IpfsHash;
const imageData = $('Create NFT Metadata').item.json;

// Parse transaction result
const result = {
  mint_id: baseData.mint_id,
  timestamp: baseData.timestamp,
  nft_data: {
    token_id: mintResult.tokenId,
    contract_address: mintResult.contractAddress,
    network: baseData.network,
    collection: baseData.collection,
    name: baseData.metadata.name,
    description: baseData.metadata.description
  },
  ipfs_data: {
    image_hash: imageData.image_ipfs_hash,
    image_url: imageData.image_ipfs_url,
    metadata_hash: metadataHash,
    metadata_url: `https://gateway.pinata.cloud/ipfs/${metadataHash}`
  },
  blockchain_data: {
    transaction_hash: mintResult.transactionHash,
    block_number: mintResult.blockNumber,
    gas_used: mintResult.gasUsed,
    status: mintResult.status === 1 ? 'success' : 'failed'
  },
  marketplace_urls: {
    opensea: `https://opensea.io/assets/${baseData.network}/${mintResult.contractAddress}/${mintResult.tokenId}`,
    rarible: `https://rarible.com/token/${mintResult.contractAddress}:${mintResult.tokenId}`,
    looksrare: `https://looksrare.org/collections/${mintResult.contractAddress}/${mintResult.tokenId}`
  },
  metadata: {
    minting_time_ms: Date.now() - new Date(baseData.timestamp).getTime()
  }
};

return { json: result };

